namespace PdfKnead.EInvoice;

/// <summary>
/// The labels of the business terms and groups in German and English, from the XRechnung visualization of the KoSIT (Apache-2.0;
/// Zuordnung/bezeichnungen.tsv, generated by Zuordnung/erzeugen.py). German when the program speaks German, else English.
/// </summary>
public static class InvoiceLabels
{
    private static readonly Lazy<Dictionary<string, (string Id, string De, string En)>> Table = new(Load);

    /// <summary>
    /// The names of the business groups of EN 16931 (own short wording; the visualization labels only some groups, as headings of its views).
    /// </summary>
    private static readonly Dictionary<string, (string De, string En)> Groups = new(StringComparer.Ordinal)
    {
        ["BG-1"] = ("Bemerkung zur Rechnung", "Invoice note"),
        ["BG-2"] = ("Prozesssteuerung", "Process control"),
        ["BG-3"] = ("Vorausgegangene Rechnung", "Preceding invoice"),
        ["BG-4"] = ("Verkäufer", "Seller"),
        ["BG-5"] = ("Anschrift des Verkäufers", "Seller postal address"),
        ["BG-6"] = ("Kontakt des Verkäufers", "Seller contact"),
        ["BG-7"] = ("Käufer", "Buyer"),
        ["BG-8"] = ("Anschrift des Käufers", "Buyer postal address"),
        ["BG-9"] = ("Kontakt des Käufers", "Buyer contact"),
        ["BG-10"] = ("Zahlungsempfänger", "Payee"),
        ["BG-11"] = ("Steuerlicher Vertreter des Verkäufers", "Seller tax representative"),
        ["BG-12"] = ("Anschrift des steuerlichen Vertreters", "Tax representative postal address"),
        ["BG-13"] = ("Lieferung", "Delivery"),
        ["BG-14"] = ("Abrechnungszeitraum", "Invoicing period"),
        ["BG-15"] = ("Lieferanschrift", "Deliver-to address"),
        ["BG-16"] = ("Zahlungsanweisungen", "Payment instructions"),
        ["BG-17"] = ("Überweisung", "Credit transfer"),
        ["BG-18"] = ("Zahlungskarte", "Payment card"),
        ["BG-19"] = ("Lastschrift", "Direct debit"),
        ["BG-20"] = ("Nachlass auf Rechnungsebene", "Document level allowance"),
        ["BG-21"] = ("Zuschlag auf Rechnungsebene", "Document level charge"),
        ["BG-22"] = ("Gesamtbeträge", "Document totals"),
        ["BG-23"] = ("Aufschlüsselung der Umsatzsteuer", "VAT breakdown"),
        ["BG-24"] = ("Rechnungsbegründende Unterlage", "Additional supporting document"),
        ["BG-25"] = ("Rechnungsposition", "Invoice line"),
        ["BG-26"] = ("Abrechnungszeitraum der Position", "Invoice line period"),
        ["BG-27"] = ("Nachlass auf Positionsebene", "Invoice line allowance"),
        ["BG-28"] = ("Zuschlag auf Positionsebene", "Invoice line charge"),
        ["BG-29"] = ("Preis", "Price details"),
        ["BG-30"] = ("Umsatzsteuer der Position", "Line VAT information"),
        ["BG-31"] = ("Artikel", "Item information"),
        ["BG-32"] = ("Artikeleigenschaft", "Item attribute"),
        // the sub invoice lines of the XRechnung extension (UBL SubInvoiceLine; CII ParentLineID, built by hand)
        ["BG-DEX-01"] = ("Unterposition", "Sub invoice line"),
        ["BG-DEX-02"] = ("Artikel der Unterposition", "Sub invoice line item information"),
        ["BG-DEX-03"] = ("Nachlass der Unterposition", "Sub invoice line allowance"),
        ["BG-DEX-04"] = ("Zuschlag der Unterposition", "Sub invoice line charge"),
        ["BG-DEX-05"] = ("Abrechnungszeitraum der Unterposition", "Sub invoice line period"),
        ["BG-DEX-06"] = ("Umsatzsteuer der Unterposition", "Sub invoice line VAT information"),
        ["BG-DEX-07"] = ("Preis der Unterposition", "Sub invoice line price details"),
    };

    /// <summary>The label of a name of the mapping („Invoice_number“); the identifier or the name if the table has none.</summary>
    /// <param name="name">The name in the mapping.</param>
    /// <param name="id">The identifier, shown if there is no label.</param>
    public static string Of(string name, string id)
    {
        if (Groups.TryGetValue(id, out var group)) return Tr.Current.IsGerman ? group.De : group.En;
        if (!Table.Value.TryGetValue("xr:" + name, out var label))
        {
            // a group of the XRechnung extension: the heading the visualization gives it, else its name
            var byId = Table.Value.Where(e => e.Value.Id == id).Select(e => e.Value).FirstOrDefault();
            if (byId.De is not null) return Tr.Current.IsGerman || string.IsNullOrEmpty(byId.En) ? byId.De : byId.En;
            return string.IsNullOrEmpty(name) ? id : name;
        }
        var text = Tr.Current.IsGerman ? label.De : label.En;
        return string.IsNullOrEmpty(text) ? label.De : text;
    }

    /// <summary>A label of the table by its key without the prefix („_gross“) — the words of the representation; null if absent.</summary>
    public static string? Word(string key) =>
        Table.Value.TryGetValue(key, out var label) ? (Tr.Current.IsGerman ? label.De : label.En) : null;

    /// <summary>How many labels the table has (tests).</summary>
    internal static int Count => Table.Value.Count;

    private static Dictionary<string, (string, string, string)> Load()
    {
        var table = new Dictionary<string, (string, string, string)>(StringComparer.Ordinal);
        foreach (var line in InvoiceMap.Resource("bezeichnungen.tsv"))
        {
            if (line.Length == 0 || line[0] == '#') continue;
            var cols = line.Split('\t');
            if (cols.Length < 4) throw new InvalidDataException("bezeichnungen.tsv: zu wenige Spalten");
            table[cols[1]] = (cols[0], cols[2], cols[3]);
        }
        return table;
    }
}
